import {SKILL_TREE_DESCRIPTIONS} from './skill-tree-descriptions.js';
import {SKILL_TREE_DEFINITION as D} from './skill-tree-definition.js';
import {normalizeSkillTree,skillPointBudget,skillPresetCost,validSkillTree} from './skill-tree-state.js';
import {icon} from './icons.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=ids=>ids.map(id=>D.nodes.find(n=>n.id===id)?.name??id).join('、');
const choices=[['always','可用即施放'],['low','生命低于60%'],['charge','敌人将重击'],['burn','目标已灼烧']];
export function renderSkillTree(m){const p=m.draft.skillTree.presets[m.index],budget=skillPointBudget(m.draft),spent=skillPresetCost(p,D),blocked=m.busy||m.blocked;return `<section class="skillTreeEditor"><header><h2>战技树 · 方案${m.index+1}</h2><span>已用 ${spent} / ${budget} 点 · 全树99点</span></header><p>草稿仅在确认后生效；每套方案独立使用相同点数。天赋与装备不变。</p><nav>${m.draft.skillTree.presets.map((q,i)=>`<button data-tree-action="plan" data-tree-id="${i}" aria-pressed="${i===m.index}" ${blocked?'disabled':''}>${esc(q.name)}${i===m.draft.skillTree.selectedPreset?' · 当前':''}${i===m.index?' · 编辑中':''}</button>`).join('')}</nav>${m.draft.skillTree.mode!=='active'?'<aside class="treeLegacy">旧14战技及装备方案快照保留。首次确认转换后需使用新树配置；保存草稿不会启用新战斗技能。转换需明确确认且当前战斗必须先完成，不会自动赠送节点或填补空槽。</aside>':''}<div class="treeNodes">${D.nodes.map(n=>{const learned=p.unlocked.includes(n.id),available=n.requires.every(id=>p.unlocked.includes(id))&&spent+n.cost<=budget;const description=SKILL_TREE_DESCRIPTIONS[n.id];return `<article class="treeNodeCard"><button class="treeNode ${learned?'learned':''}" data-tree-action="node" data-tree-id="${n.id}" ${blocked||!learned&&!available?'disabled':''} aria-pressed="${learned}" title="${esc(n.requires.length?'前置：'+names(n.requires):'无前置')}">${icon(n.kind==='passive'?'shield':'sword')}<strong>${esc(n.name)}</strong><small>${n.kind==='passive'?'被动':'主动'} · ${n.cost}点${learned?' · 已学':''}</small><small>${n.requires.length?'前置 '+esc(names(n.requires)):'根节点'}</small></button><details class="treeSkillDescription"><summary>技能效果</summary>${[description?.base,description?.axe,description?.hammer].filter(Boolean).map(text=>`<p>${esc(text)}</p>`).join('')}${n.kind==='passive'?'<p>仅装入两个被动槽之一后生效。</p>':''}</details></article>`;}).join('')}</div><div class="treeSlots">${['active','passive'].map(kind=>`<section><h3>${kind==='active'?'4主动 · 上至下释放优先级':'2被动 · 学会后需装入才生效'}</h3>${p[kind].map((value,i)=>`<div class="treeSlot"><label>${kind==='active'?'主动':'被动'} ${i+1}<select data-tree-slot="${kind}" data-tree-index="${i}" ${blocked?'disabled':''}><option value="">留空</option>${D.nodes.filter(n=>n.kind===kind&&p.unlocked.includes(n.id)).map(n=>`<option value="${n.id}" ${value===n.id?'selected':''} ${p[kind].includes(n.id)&&value!==n.id?'disabled':''}>${esc(n.name)}</option>`).join('')}</select></label>${kind==='active'?`<select aria-label="主动${i+1}释放条件" data-tree-condition="${i}" ${blocked?'disabled':''}>${choices.map(([id,label])=>`<option value="${id}" ${p.conditions[i]===id?'selected':''}>${label}</option>`).join('')}</select>`:''}</div>`).join('')}</section>`).join('')}</div>${m.refund?`<aside class="treeReview"><h3>确认退还 ${m.refund.points} 点？</h3><p>将退还：${esc(names(m.refund.ids))}。相关主动/被动将出槽，不自动替补。</p><button data-tree-action="refund-confirm" ${blocked?'disabled':''}>确认退还至草稿</button><button data-tree-action="refund-cancel">取消退款</button></aside>`:''}${m.activationReview?'<aside class="treeReview"><h3>确认转换并应用新树？</h3><p>旧配置快照保留；新树按当前草稿生效，空槽保持空白。不会替换装备或角色天赋。</p><button data-tree-action="activate-confirm">确认转换并保存</button><button data-tree-action="activate-cancel">返回编辑</button></aside>':''}<p role="status">${esc(m.error|| (m.blocked?'请先停止远征并完成当前战斗/副本，再应用变更。':''))}</p><footer><button data-tree-action="reset" ${blocked?'disabled':''}>免费重置本方案</button><button data-tree-action="cancel" ${m.busy?'disabled':''}>取消草稿</button><button class="primary" data-tree-action="commit" ${blocked||m.refund?'disabled':''}>${m.busy?'正在保存…':m.draft.skillTree.mode==='active'?'确认应用':'保存草稿配置'}</button>${m.draft.skillTree.mode!=='active'?`<button data-tree-action="activate-review" ${blocked||m.refund||m.activationAllowed===false?'disabled':''}>${m.activationAllowed===false?'战斗转换待开放':'转换并应用…'}</button>`:''}</footer></section>`;}
export function mountSkillTree(host,adapter){let disposed=false,m;
 const reset=()=>{const live=adapter.getState(),draft=structuredClone(live);if(!normalizeSkillTree(draft,D))throw Error('invalid skill tree');m={baseState:structuredClone(live),draft,index:draft.skillTree.selectedPreset,beforeTree:structuredClone(live.skillTree??null),busy:false,blocked:false,activationAllowed:adapter.canActivate!==false,error:'',refund:null,activationReview:false};};
 const paint=()=>{if(disposed)return;const live=adapter.getState();m.blocked=!!live.running||!!live.dungeonRun||!!live.activeEncounter&&!live.activeEncounter.rewarded;host.innerHTML=renderSkillTree(m);};
 const changeDraft=fn=>{const next=structuredClone(m.draft);fn(next.skillTree.presets[m.index]);if(!validSkillTree(next,D)){m.error='配置无效：请检查前置、点数与重复技能';return false;}m.draft=next;m.error='';m.activationReview=false;return true;};
 const refund=ids=>{let set=new Set(ids),p=m.draft.skillTree.presets[m.index];for(let previous=-1;previous!==set.size;){previous=set.size;for(const n of D.nodes)if(p.unlocked.includes(n.id)&&n.requires.some(id=>set.has(id)))set.add(n.id);}const list=p.unlocked.filter(id=>set.has(id));m.refund={ids:list,points:D.nodes.filter(n=>list.includes(n.id)).reduce((a,n)=>a+n.cost,0)};};
 const commit=async activate=>{if(m.busy||m.blocked)return;m.busy=true;m.error='';paint();try{const result=await adapter.commit({baseState:structuredClone(m.baseState),beforeTree:structuredClone(m.beforeTree),presets:structuredClone(m.draft.skillTree.presets),activate});if(disposed)return;if(result?.ok){reset();m.error='已保存';}else m.error=result?.reason||'保存失败，草稿保留；未应用变更';}catch{m.error='保存失败，草稿保留；未应用变更';}finally{m.busy=false;paint();}};
 const click=async ev=>{const b=ev.target.closest('[data-tree-action]');if(!b||!host.contains(b)||b.disabled)return;const action=b.dataset.treeAction;paint();if(m.busy)return;if(action==='cancel'){reset();adapter.onCancel?.();paint();return;}if(m.blocked)return;
 if(action==='plan'){const i=Number(b.dataset.treeId);if(Number.isInteger(i)&&i>=0&&i<3){m.index=i;m.refund=null;m.activationReview=false;}}
 if(action==='node'){const n=D.nodes.find(n=>n.id===b.dataset.treeId);if(n){if(m.draft.skillTree.presets[m.index].unlocked.includes(n.id))refund([n.id]);else changeDraft(p=>p.unlocked.push(n.id));}}
 if(action==='reset')refund([...m.draft.skillTree.presets[m.index].unlocked]);
 if(action==='refund-cancel')m.refund=null;
 if(action==='refund-confirm'&&m.refund){const ids=m.refund.ids;changeDraft(p=>{p.unlocked=p.unlocked.filter(id=>!ids.includes(id));p.active=p.active.map((id,i)=>{if(ids.includes(id)){p.conditions[i]='always';return null;}return id;});p.passive=p.passive.map(id=>ids.includes(id)?null:id);});m.refund=null;}
 if(action==='activate-cancel')m.activationReview=false;
 if(action==='commit'&&!m.refund)await commit(false);if(action==='activate-review'&&m.activationAllowed&&!m.refund&&m.draft.skillTree.mode!=='active')m.activationReview=true;
 if(action==='activate-confirm'&&m.activationReview)await commit(true);paint();};
 const change=ev=>{const t=ev.target;if(m.busy||m.blocked||!host.contains(t))return;const kind=t.dataset.treeSlot,index=Number(t.dataset.treeIndex);if(['active','passive'].includes(kind)&&Number.isInteger(index)&&index>=0&&index<(kind==='active'?4:2))changeDraft(p=>p[kind][index]=t.value||null);if(t.dataset.treeCondition!==undefined){const i=Number(t.dataset.treeCondition);if(Number.isInteger(i)&&i>=0&&i<4&&choices.some(([id])=>id===t.value))changeDraft(p=>p.conditions[i]=t.value);}paint();};
 reset();paint();host.addEventListener('click',click);host.addEventListener('change',change);return {refresh:paint,getDraft:()=>structuredClone(m.draft),dispose(){disposed=true;host.removeEventListener?.('click',click);host.removeEventListener?.('change',change);}};
}
